H=[[4,6,8,8,6,8],[2]*20,[2]+[4]*10+[6]*3,[2]*20,[4 if i in [36,37,38] else 2 for i in range(1,46)], [4 if i in [9,11,12,13,14,17,19,20] else (6 if i==18 else 2) for i in range(1,21)]]
MT=[[2,2,2,2,2,4],[0]*6+[1]*14,[1]*7+[2]*7,[0]*6+[1]*14,[0]*11+[1]*34,[1]*19+[2]]
mods=[]
for mi,(block,md) in enumerate(zip(blocks,meta)):
 code,title,h,n,a,mt,pages,icon,desc=md
 rows=block.strip().splitlines(); lessons=[]
 for li,row in enumerate(rows):
  name,explain,control,task=row.split('|'); idx=li+1
  lessons.append(dict(id=f'm{mi+1}-l{idx}',number=idx,title=name,hours=H[mi][li],theory=N[mi][li],practice=H[mi][li]-N[mi][li],independent=MT[mi][li],explain=explain,control=control,task=task))
 mods.append(dict(id=mi+1,code=code,title=title,hours=h,theory=n,practice=a,independent=mt,pages=pages,icon=icon,description=desc,lessons=lessons))
assert [len(m['lessons']) for m in mods]==[6,20,14,20,45,20]
for m in mods:
 for field in ['hours','theory','practice','independent']:
  assert sum(l[field] for l in m['lessons'])==m[field],(m['title'],field,sum(l[field] for l in m['lessons']),m[field])
(root/'course/data.json').write_text(json.dumps(mods,ensure_ascii=False,indent=2))
print('Validated',sum(len(m['lessons']) for m in mods),'topics;',sum(m['hours'] for m in mods),'hours')
